document.addEventListener('DOMContentLoaded',()=>{const t=document.querySelector('.menu-toggle'),n=document.querySelector('.nav');t?.addEventListener('click',()=>{const open=n.classList.toggle('open');t.setAttribute('aria-expanded',open);});document.querySelectorAll('.nav-drop>button').forEach(b=>b.addEventListener('click',e=>{if(innerWidth>1000)return;e.preventDefault();const d=b.parentElement;document.querySelectorAll('.nav-drop').forEach(x=>x!==d&&x.classList.remove('open'));d.classList.toggle('open');b.setAttribute('aria-expanded',d.classList.contains('open'));}));const f=document.querySelector('[data-project-form]');f?.addEventListener('submit',async e=>{e.preventDefault();if(!f.checkValidity()){f.reportValidity();return}const data=new FormData(f),s=f.querySelector('.form-status'),btn=f.querySelector('button[type=submit]');if(data.get('_honey'))return;
const payload={_subject:`Website inquiry: ${data.get('project')||'New project'}`,_template:'table',_replyto:data.get('email'),Name:data.get('name'),Email:data.get('email'),Organization:data.get('organization'),Need:data.get('project'),'Data residency':data.get('residency'),Timeline:data.get('timeline'),Details:data.get('message'),Page:location.href};
btn.disabled=true;s.className='form-status';s.textContent='Sending your inquiry…';
try{const r=await fetch('https://formsubmit.co/ajax/info@ashitconsulting.ai',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify(payload)});const j=await r.json().catch(()=>({}));if(!r.ok||String(j.success)!=='true'){console.warn('Form service reply:',r.status,j);const er=new Error(j.message||r.status);er.activation=/activat/i.test(j.message||'');throw er}
f.reset();s.classList.add('ok');s.textContent='Thank you. Your inquiry has been sent, and a senior engineer will reply shortly.'}
catch(err){s.classList.add('err');s.innerHTML=(err.activation?'This form is being activated and could not deliver your message yet. ':'Sorry, that did not go through. ')+'Please email us at <a href="mailto:info@ashitconsulting.ai">info@ashitconsulting.ai</a>.'}
finally{btn.disabled=false}});});
document.addEventListener('DOMContentLoaded',()=>{const els=document.querySelectorAll('[data-reveal]');if(!els.length||!('IntersectionObserver'in window)||matchMedia('(prefers-reduced-motion: reduce)').matches){els.forEach(e=>e.classList.add('in'));return}const io=new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting)return;const sib=[...e.target.parentElement.children].filter(x=>x.hasAttribute('data-reveal'));e.target.style.transitionDelay=`${Math.min(sib.indexOf(e.target),5)*40}ms`;e.target.classList.add('in');io.unobserve(e.target)}),{rootMargin:'0px 0px -8% 0px',threshold:.12});els.forEach(e=>io.observe(e))});
